# memup/batch.py ---------------------------------------------------
from collections import defaultdict
from typing import List
import torch, numpy as np
from datagen import Trajectory

class MemupBatch:
    """Holds a batch consisting of truncated sub-trajectories + indices
    needed for the MemUP training objective (memory roll-outs, prediction
    points and chosen target steps)."""
    def __init__(self, trajs, mem_idx, pred_idx, target_idx):
        self.trajs: List[Trajectory] = trajs      # original trajectories
        self.mem_idx = mem_idx                    # indices processed by RNN
        self.pred_idx = pred_idx                  # indices whose hidden state is used for prediction
        self.target_idx = target_idx              # future targets chosen by selector

# helper -----------------------------------------------------------

def slice_to_torch(seq, idx, device="cpu"):
    arr = np.asarray(seq)
    if idx is not None:
        arr = arr[np.asarray(idx)]
    return torch.as_tensor(arr, device=device)

class TrajectorySlicer:
    """Utility that given a list of trajectories + list of indices returns
    a dict of torch.Tensor batches that can be directly fed into a neural
    module."""
    def __init__(self, keys):
        self.keys = set(keys)
    def process(self, trajs, indices, device="cpu"):
        if indices is None:
            indices = [None]*len(trajs)
        data = defaultdict(list)
        for idx, tr in zip(indices, trajs):
            for k in self.keys:
                data[k].append(slice_to_torch(tr.data[k], idx, "cpu"))
        for k in self.keys:
            lens = [t.shape[0] for t in data[k]]
            flat = torch.cat(data[k]).to(device)
            data[k] = torch.split(flat, lens)
        return data

