import numpy as np, torch
class TargetSelector:
    def __init__(self, k, time_dependent_selection=True, uncertainty_key='uncertainty'):
        self.k=k; self.time_dependent_selection=time_dependent_selection; self.uncertainty_key=uncertainty_key
    def select_target_idx(self, traj, pred_steps=None):
        raise NotImplementedError()

class TopKSelector(TargetSelector):
    def select_target_idx(self, traj, pred_steps=None):
        a=np.asarray(traj.data[self.uncertainty_key]); n=len(a)
        if pred_steps is None: pred_steps=np.arange(n)
        top=np.argsort(a)[-self.k:]
        if not self.time_dependent_selection:
            return [list(top)]*len(pred_steps)
        res=[]; top=set(top); next_cand=n-self.k-1
        for t in pred_steps:
            top={i for i in top if i>=t}
            while len(top)<self.k and next_cand>=0:
                if a.argsort()[next_cand]>=t: top.add(a.argsort()[next_cand])
                next_cand-=1
            lst=list(top)
            if len(lst)<self.k: lst.extend(np.random.choice(lst, self.k-len(lst)))
            res.append(lst)
        return res

class CurrentStepSelector(TargetSelector):
    def __init__(self): super().__init__(1,True)
    def select_target_idx(self, traj, pred_steps=None):
        if pred_steps is None: pred_steps=np.arange(len(traj))
        return np.asarray(pred_steps).reshape(-1,1)

