#   – surprise/uncertainty estimation  (–log p(y) here realised via
#     prediction error).
from typing import List, Optional
class UncertaintyDetector:
    def __init__(self, uncertainty_key='uncertainty'): self.uncertainty_key=uncertainty_key
    def make_estimate(self,trajs:List[Trajectory]): raise NotImplementedError()
    def process_(self,trajs):
        est=self.make_estimate(trajs)
        for e,t in zip(est,trajs): t.data[self.uncertainty_key]=e
        return trajs

class PredictionErrorBasedDetector(UncertaintyDetector):
    def __init__(self, mem, pred, err_metric, context_key=None, uncertainty_key='uncertainty'):
        super().__init__(uncertainty_key); self.mem=mem; self.pred=pred; self.err=err_metric; self.context_key=context_key
    @torch.no_grad()
    def make_estimate(self,trajs):
        L=[len(t) for t in trajs]
        idx=[np.arange(l) for l in L]
        batch=MemupBatch(trajs,idx,idx,[i.reshape(-1,1) for i in idx])
        state=self.mem.init_state(len(trajs))
        mem_out,_=self.mem.process_batch(batch,state)
        if self.context_key:
            ctx=torch.split(mem_out.cpu(),L)
            for c,t in zip(ctx,trajs): t.data[self.context_key]=c
        pstate=self.pred.init_state(len(trajs))
        out=self.pred.process_batch(batch,mem_out,pstate)
        err=self.err(out['preds'],out['targets']).reshape(-1)
        return torch.split(err.cpu(),L)

