#   – handling truncated BPTT windows + attaching selector & detector.
from copy import copy
class TruncatedMemUPSampler:
    def __init__(self,sampler,target_selector,dynamic_preproc=None,prediction_frequency=1,rollout=1):
        self.sampler=sampler; self.sel=target_selector; self.pred_freq=prediction_frequency
        self.preproc=dynamic_preproc; self.rollout=rollout
        self._mem_off=None; self._lens=None; self._buf=None; self._bs=None
    def _init(self,bs):
        if self._bs!=bs: self._bs=bs; self._mem_off=np.zeros(bs,int); self._lens=np.zeros(bs,int); self._buf=None
    def _fill(self):
        done=self._mem_off>=self._lens
        ids=np.nonzero(done)[0]
        if not len(ids): return
        new=self.sampler.sample(len(ids)); lengths=[len(t) for t in new]
        if self.preproc: new=self.preproc.process(new)
        new_batch=self._make_batch(new)
        self._lens[ids]=lengths; self._mem_off[ids]=0
        if len(ids)==self._bs: self._buf=new_batch
        else: self._buf.update_indices(ids,new_batch)
    def _make_batch(self,trajs):
        batch=MemupBatch([],[],[],[])
        for tr in trajs:
            pred_idx=self._pred_idx(0,len(tr))
            tgt=self.sel.select_target_idx(tr,pred_idx)
            batch.trajs.append(tr)
            batch.mem_idx.append(np.arange(len(tr)))
            batch.pred_idx.append(pred_idx)
            batch.target_idx.append(tgt)
        return batch
    def _pred_idx(self,s,e):
        idx=list(np.arange(s,e+1,self.pred_freq)[1:]-1)
        if (e-1) not in idx[-1:]: idx.append(e-1)
        return idx
    def epoch(self,batch_size,num_batches):
        self._init(batch_size)
        for _ in range(num_batches):
            self._fill()
            yield self._next()
    def _next(self):
        batch=copy(self._buf)
        for i in range(self._bs):
            m0=self._mem_off[i]; m1=min(m0+self.rollout,len(batch.trajs[i]))
            batch.mem_idx[i]=np.arange(m0,m1)
            preds=self._pred_idx(m0,m1)
            batch.pred_idx[i]=preds
            batch.target_idx[i]=[batch.target_idx[i][j] for j in preds]
        self._mem_off+=self.rollout
        return batch

# memup/memory.py --------------------------------------------------
class MemUPMemory:
    """Wrapper around user-provided RNN (g_θ). Handles slicing of data,
    runs forward pass, then selects only those hidden states corresponding
    to prediction points (|pred_idx|) so that gradients are propagated only
    through r+K steps."""
    def __init__(self, module):
        self.memory=module
        self.prep=TrajectorySlicer(module.input_keys())
    @property
    def device(self): return self.memory.device
    def init_state(self,b): return self.memory.init_state(b)
    def detach_state(self,s): return self.memory.detach_state(s)
    def process_batch(self,batch,state):
        inp=self.prep.process(batch.trajs,batch.mem_idx,self.device)
        out,state=self.memory(inp,state)
        filt=self._filter(out,batch)
        return filt,state
    def _filter(self,out,batch):
        ids=[]; L=out.shape[1]; shift=0
        for idx,m in zip(batch.pred_idx,batch.mem_idx):
            ids.append(torch.as_tensor(idx)-m[0]+shift); shift+=L
        return out.flatten(0,1)[torch.cat(ids).long().to(self.device)]

# memup/predictor.py ----------------------------------------------
#   – q_ϕ (with or without internal context RNN)
class RNNMemUPPredictor:
    def __init__(self,module,target_key='y'):
        self.pred=module; self.tgt=target_key
        self.prep=TrajectorySlicer([*module.input_keys(),target_key])
    @property
    def device(self): return self.pred.device
    def init_state(self,b): return self.pred.init_state(b)
    def process_batch(self,batch,mem_out,state):
        mem_exp=self._expand(mem_out,batch.target_idx)
        inputs,targets=self._extract(batch)
        preds,ctx,state=self.pred(inputs,mem_exp,state)
        return dict(preds=preds,targets=targets,pred_state=state)
    def _extract(self,batch):
        flat=[list(np.concatenate(idx)) for idx in batch.target_idx]
        data=self.prep.process(batch.trajs,flat,self.device)
        targets=torch.cat(data.pop(self.tgt))
        return data,targets
    def _expand(self,mem,target_idx):
        sel=[torch.ones(len(idx),dtype=torch.int64,device=mem.device)*i for i,idx in enumerate(np.concatenate(target_idx))]
        return mem[torch.cat(sel)]

# memup/training.py ------------------------------------------------
from itertools import chain

def update_on_batch_two_rnn(batch,memory,predictor,mem_state,pred_state,crit,opt,clip=1.,mult=1.):
    mem_out,mem_state=memory.process_batch(batch,mem_state)
    out=predictor.process_batch(batch,mem_out,pred_state)
    loss=crit(out['preds'],out['targets'])
    opt.zero_grad(); (loss*mult).backward();
    if clip:
        torch.nn.utils.clip_grad_norm_(chain(memory.memory.parameters(), predictor.pred.parameters()), clip)
    opt.step()
    return dict(loss=loss.item(),mem_state=memory.detach_state(mem_state),pred_state=predictor.detach_state(out['pred_state']))

