from abc import ABC, abstractmethod
import numpy as np
import torch
from typing import List, Optional
from datagen import Trajectory
from .batch import MemupBatch

class UncertaintyDetector(ABC):
    def __init__(self, uncertainty_key='uncertainty'):
        self.uncertainty_key = uncertainty_key

    @abstractmethod
    def make_estimate(self, trajectories: List[Trajectory]):
        pass

    def process_(self, trajectories: List[Trajectory]):
        estimates = self.make_estimate(trajectories)
        for est, tr in zip(estimates, trajectories):
            tr.data[self.uncertainty_key] = est
        return trajectories

class PredictionErrorBasedDetector(UncertaintyDetector):
    """d_ψ : surprise = loss(ŷ , y)"""
    def __init__(self, memup_memory, memup_predictor, error_metric, uncertainty_key='uncertainty'):
        super().__init__(uncertainty_key)
        self.memup_memory = memup_memory
        self.memup_predictor = memup_predictor
        self.error_metric = error_metric

    @torch.no_grad()
    def make_estimate(self, trajectories):
        lengths = [len(t) for t in trajectories]
        idx = [np.arange(l) for l in lengths]
        batch = MemupBatch(trajectories, idx, idx, [e.reshape(-1, 1) for e in idx])
        mem_state = self.memup_memory.init_state(len(trajectories))
        mem_output, _ = self.memup_memory.process_batch(batch, mem_state)
        pred_state = self.memup_predictor.init_state(len(trajectories))
        out = self.memup_predictor.process_batch(batch, mem_output, pred_state)
        errors = self.error_metric(out['preds'], out['targets']).reshape(-1)
        return torch.split(errors.cpu(), lengths)
