import numpy as np
import torch
from abc import ABC, abstractmethod

class TargetSelector(ABC):
    def __init__(self, k, time_dependent_selection=True, uncertainty_key='uncertainty'):
        self.k = k
        self.time_dependent_selection = time_dependent_selection
        self.uncertainty_key = uncertainty_key

    @abstractmethod
    def target_idx_from_estimate(self, uncertainty_estimate, mem_prediction_steps=None):
        pass

    def select_target_idx(self, trajectory, mem_prediction_steps=None):
        return self.target_idx_from_estimate(trajectory.data[self.uncertainty_key], mem_prediction_steps)

class TopKSelector(TargetSelector):
    """Select K most uncertain future steps (Gumbel-Max/softmax optional)."""
    def target_idx_from_estimate(self, uncertainty_estimate, mem_prediction_steps=None):
        a = np.asarray(uncertainty_estimate)
        if mem_prediction_steps is None:
            mem_prediction_steps = np.arange(len(a))
        top_idx = np.argsort(a)
        n = len(a)
        top_k_set = set(top_idx[-self.k:])
        out = []
        for t in mem_prediction_steps:
            if self.time_dependent_selection:
                top_k_set = {i for i in top_k_set if i >= t}
            while len(top_k_set) < self.k:
                cand = np.random.choice(np.setdiff1d(np.arange(n), list(top_k_set)))
                if (not self.time_dependent_selection) or (cand >= t):
                    top_k_set.add(cand)
            out.append(list(top_k_set)[:self.k])
        return out
