from typing import Iterable
import numpy as np
from copy import copy
from datagen import TrajectorySampler
from memup.batch import MemupBatch

class TruncatedMemUPSampler(object):
    """Implements truncated BPTT (rollout «r») and prediction frequency."""
    def __init__(self, traj_sampler: TrajectorySampler, target_selector: TargetSelector, dynamic_preprocessor=None, prediction_frequency=1, rollout=1):
        self.traj_sampler = traj_sampler
        self.target_selector = target_selector
        self.preproc = dynamic_preprocessor
        self.pred_freq = prediction_frequency
        self.rollout = rollout
        # stateful buffers for streaming batches --------------
        self._mem_offset = None
        self._ep_lengths = None
        self._batch_buffer = None
        self._batch_size = None

    def sample(self, batch_size):
        self._init_buffers(batch_size)
        self._fill_batch()
        return self._next_rollout()

    # Helpers --------------------------------------------------
    def _init_buffers(self, batch_size):
        if self._batch_buffer is None:
            self._batch_size = batch_size
            self._mem_offset = np.zeros(batch_size, dtype=int)
            self._ep_lengths = np.zeros(batch_size, dtype=int)
            self._batch_buffer = None

    def _fill_batch(self):
        done = self._mem_offset >= self._ep_lengths
        ids = np.nonzero(done)[0]
        if len(ids):
            new_trajs = self.traj_sampler.sample(len(ids))
            if self.preproc:
                new_trajs = self.preproc.process(new_trajs)
            self._ep_lengths[ids] = [len(t) for t in new_trajs]
            new_batch = self._make_batch(new_trajs)
            if self._batch_buffer is None or len(ids) == self._batch_size:
                self._batch_buffer = new_batch
            else:
                self._batch_buffer.update_indices(ids, new_batch)
            self._mem_offset[ids] = 0

    def _make_batch(self, trajs):
        batch = MemupBatch([], [], [], [])
        for tr in trajs:
            pred_idx = self._prediction_idx(0, len(tr))
            targets = self.target_selector.select_target_idx(tr, pred_idx)
            batch.trajs.append(tr)
            batch.mem_idx.append(np.arange(len(tr)))
            batch.pred_idx.append(pred_idx)
            batch.target_idx.append(targets)
        return batch

    def _prediction_idx(self, start, end):
        idx = list(np.arange(start, end + 1, self.pred_freq)[1:] - 1)
        if (end - 1) not in idx:
            idx.append(end - 1)
        return idx

    def _next_rollout(self):
        batch = copy(self._batch_buffer)
        for i in range(self._batch_size):
            s = self._mem_offset[i]
            e = min(s + self.rollout, len(batch.trajs[i]))
            batch.mem_idx[i] = np.arange(s, e)
            preds = self._prediction_idx(s, e)
            batch.pred_idx[i] = preds
            batch.target_idx[i] = [batch.target_idx[i][t] for t in preds]
        self._mem_offset += self.rollout
        return batch
