import torch
import numpy as np
from .batch import TrajectorySlicer, MemupBatch

class MemUPMemory(object):
    """Wrapper around g_θ (RNN) that exposes helper utilities."""
    def __init__(self, memory_module):
        self.memory = memory_module
        self.preproc = TrajectorySlicer(memory_module.input_keys())

    def process_batch(self, batch: MemupBatch, mem_state):
        mem_in = self.preproc.process(batch.trajs, batch.mem_idx, self.device)
        output, mem_state = self.memory(mem_in, mem_state)
        output = self._filter_output(output, batch)
        return output, mem_state

    def _filter_output(self, mem_output, batch):
        res_ids = []
        L = mem_output.shape[1]
        shift = 0
        for idx, m_idx in zip(batch.pred_idx, batch.mem_idx):
            res_ids.append(torch.as_tensor(idx) - m_idx[0] + shift)
            shift += L
        ids = torch.cat(res_ids).long().to(self.device)
        return mem_output.flatten(0, 1)[ids]

    # Convenience ------------------------------------------------
    def init_state(self, batch):
        return self.memory.init_state(batch)

    def detach_state(self, s):
        return self.memory.detach_state(s)

    @property
    def device(self):
        return self.memory.device
