from itertools import chain
import torch
from typing import List
from .batch import TrajectorySlicer, MemupBatch
from .nets import PredictorModule, PredictorModuleWithContext

class AbstractMemUPPredictor:
    def __init__(self, input_keys, target_key='y'):
        self.target_key = target_key
        self.input_keys = input_keys
        self.preproc = TrajectorySlicer([*input_keys, target_key])

    @staticmethod
    def expand_memory(memory_output, target_idx: List):
        index = torch.cat([torch.full((len(idx),), i, dtype=torch.long, device=memory_output.device) for i, idx in enumerate(chain(*target_idx))])
        return memory_output[index]

class RNNMemUPPredictor(AbstractMemUPPredictor):
    def __init__(self, predictor: PredictorModuleWithContext, target_key='y'):
        super().__init__(predictor.input_keys(), target_key)
        self.predictor = predictor

    @property
    def device(self):
        return self.predictor.device

    def process_batch(self, batch: MemupBatch, memory_output, pred_state):
        mem_exp = self.expand_memory(memory_output, batch.target_idx)
        inputs, targets = self.preproc.process(batch.trajs, [list(chain(*idx)) for idx in batch.target_idx], self.device), None
        targets = torch.cat(inputs.pop(self.target_key))
        preds, context, new_state = self.predictor(inputs, mem_exp, pred_state)
        return dict(preds=preds, targets=targets, pred_state=new_state)

    def init_state(self, b):
        return self.predictor.init_state(b)
