from itertools import chain
import torch

def update_on_batch_two_rnn(batch, memup_memory, memup_predictor, mem_state, pred_state, criterion, optimizer, clip_grad=1., multiplier=1.):
    """Variational lower-bound as cross-entropy (or MSE)."""
    mem_out, mem_state = memup_memory.process_batch(batch, mem_state)
    out = memup_predictor.process_batch(batch, mem_out, pred_state)
    loss = criterion(out['preds'], out['targets'])
    optimizer.zero_grad()
    (loss * multiplier).backward()
    if clip_grad:
        torch.nn.utils.clip_grad_norm_(chain(memup_memory.memory.parameters(), memup_predictor.predictor.parameters()), clip_grad)
    optimizer.step()
    return dict(loss=loss.item(), mem_state=memup_memory.detach_state(mem_state), pred_state=out['pred_state'])
